def HexDragMap(grid, on_click=None, on_drag=None,
                hover_fill="rgba(128,128,128,0.3)",
                drag_fill="rgba(255,200,0,0.4)",
                cursor="pointer", touch_layer="touch", hex_layer="hexes", **kwargs):
    """Render a HexGrid as an interactive SVG with click or drag-select support.
    
    Args:
        grid: HexGrid to render
        on_click: Callable(grid, index) -> dict of HTMX attrs per hex (click mode)
        on_drag: Dict with 'hx_post' and optionally 'hx_target', 'hx_swap'
                 e.g. {"hx_post": "/drag_select", "hx_target": "#result"}
        hover_fill: Fill on hover (click mode)
        drag_fill: Fill for hexes selected during drag
        cursor: CSS cursor on hover
        touch_layer/hex_layer: SVG layer names
        **kwargs: HTML attrs on wrapper Div (id= required for drag mode)
    """
    grid.update(layer_name=hex_layer)
    
    container_id = kwargs.get('id', f'hextm-{id(grid)}')
    kwargs['id'] = container_id
    
    # Touch style with hover
    touch_style = StyleCSS("hex-touch", fill="transparent", stroke="none", cursor=cursor)
    hover = StyleCSS("_hover", fill=hover_fill, cursor=cursor)
    touch_style.customize(hover)
    grid.builder.add_style(touch_style)
    
    # Build touch polygons
    touch_body = ""
    for i, hex_obj in enumerate(grid.hexes):
        if i not in grid.invalidRegion:
            touch_hex = Hex(hex_obj.radius, hex_obj.center, touch_style, v=hex_obj.v)
            if on_drag:
                attrs = {"data-hex-id": str(i)}
            elif on_click:
                attrs = on_click(grid, i)
            else:
                attrs = None
            touch_body += "\t" + touch_hex.svg(attrs) + "\n"
    grid.builder.adjust(touch_layer, touch_body)
    
    svg_div = Div(NotStr(grid.builder.xml()))
    
    if not on_drag:
        return Div(svg_div, **kwargs)
    
    # Drag mode: add the interaction script
    post_url = on_drag.get('hx_post', '/drag_select')
    target   = on_drag.get('hx_target', '')
    swap     = on_drag.get('hx_swap', 'innerHTML')
    
    script = Script(f"""
(function(){{
  var el = document.getElementById('{container_id}');
  var dragging = false, selected = [], fill = '{drag_fill}';
  function cleanup(e){{
    if(!dragging) return;
    dragging = false;
    el.releasePointerCapture(e.pointerId);
    el.querySelectorAll('[data-hex-id]').forEach(function(h){{ h.style.fill = ''; }});
    if(selected.length)
      htmx.ajax('POST', '{post_url}', {{
        target:'{target}', swap:'{swap}',
        values:{{ hex_ids: selected.join(',') }}
      }});
    selected = [];
  }}
  el.addEventListener('pointerdown', function(e){{
    var hex = e.target.closest('[data-hex-id]');
    if(!hex) return;
    e.preventDefault();
    dragging = true;
    selected = [hex.dataset.hexId];
    hex.style.fill = fill;
    el.setPointerCapture(e.pointerId);
  }});
  el.addEventListener('pointermove', function(e){{
    if(!dragging) return;
    var hit = document.elementFromPoint(e.clientX, e.clientY);
    if(!hit) return;
    var hex = hit.closest('[data-hex-id]');
    if(!hex) return;
    var id = hex.dataset.hexId;
    if(selected.indexOf(id) === -1){{
      selected.push(id);
      hex.style.fill = fill;
    }}
  }});
  el.addEventListener('pointerup', cleanup);
  el.addEventListener('pointercancel', cleanup);
}})();
""")
    
    return Div(svg_div, script, style="touch-action:none;", **kwargs)


