def _stretched_hex(radius, center, style, target_size):
    """Create a Hex with vertices stretched to fit target_size (width, height)."""
    sx = target_size.width / (math.sqrt(3) * radius)
    sy = target_size.height / (2 * radius)
    vertices = [
        MapCord(int(center.x + radius * Hex._COS[i] * sx),
                int(center.y + radius * Hex._SIN[i] * sy))
        for i in range(6)
    ]
    return Hex(radius, center, style, v=vertices)


def HexButtonGroup(hexes, name="selection", values=None,
                   hx_post="/select", hx_target=None, hx_swap=None,
                   direction="row", height=60, char_width=8, font_size=14,
                   hover_fill="rgba(128,128,128,0.3)", cursor="pointer",
                   **kwargs):
    """A group of hex-shaped buttons arranged in a row or column.
    
    Args:
        hexes: List of Hex objects (only .style and .label are used)
        name: Form field name (shared across group, like radio buttons)
        values: List of values to send (defaults to hex labels)
        hx_post: HTMX post URL
        hx_target: HTMX target selector
        hx_swap: HTMX swap strategy
        direction: "row" or "column"
        height: Fixed height for each hex button
        char_width: Approximate pixel width per character for width sizing
        font_size: Font size for labels
        hover_fill: Fill color on hover
        cursor: CSS cursor on hover
        **kwargs: Passed to the wrapping flex Div (id, cls, style, etc.)
    
    Returns:
        FastHTML Div containing hex button SVGs
    """
    if values is None:
        values = [h.label if h.label else str(i) for i, h in enumerate(hexes)]
    
    # Uniform width from widest label, minimum = height (square when short)
    max_chars = max((len(str(h.label)) for h in hexes), default=1)
    width = max(max_chars * char_width + char_width * 2, height)
    
    target_size = MapSize(width, height)
    radius = height / 2
    
    pad = 4
    svg_w = width + pad * 2
    svg_h = height + pad * 2
    
    # Touch style with hover
    touch_style = StyleCSS("hex-touch", fill="transparent", stroke="none", cursor=cursor)
    hover = StyleCSS("_hover", fill=hover_fill, cursor=cursor)
    touch_style.customize(hover)
    
    buttons = []
    for i, (hex_obj, value) in enumerate(zip(hexes, values)):
        center = MapCord(svg_w / 2, svg_h / 2)
        
        builder = SVGBuilder()
        builder.width = svg_w
        builder.height = svg_h
        builder.add_style(hex_obj.style)
        builder.add_style(touch_style)
        
        # Visual hex (stretched) + label
        vis_hex = _stretched_hex(radius, center, hex_obj.style, target_size)
        visual = vis_hex.svg()
        if hex_obj.label:
            visual += (f'\n\t<text x="{center.x:.1f}" y="{center.y:.1f}" '
                       f'text-anchor="middle" dominant-baseline="middle" '
                       f'font-size="{font_size}">{hex_obj.label}</text>')
        builder.adjust("visual", visual)
        
        # Touch hex (stretched) with HTMX attrs
        tch_hex = _stretched_hex(radius, center, touch_style, target_size)
        attrs = {"hx-post": hx_post}
        attrs["hx-vals"] = json.dumps({name: str(value)})
        if hx_target: attrs["hx-target"] = hx_target
        if hx_swap:   attrs["hx-swap"] = hx_swap
        builder.adjust("touch", tch_hex.svg(attrs))
        
        buttons.append(Div(NotStr(builder.xml())))
    
    # Flex container
    flex_dir = "row" if direction == "row" else "column"
    base_style = f"display:flex; flex-direction:{flex_dir}; align-items:center;"
    extra_style = kwargs.pop("style", "")
    
    return Div(*buttons, style=f"{base_style} {extra_style}", **kwargs)


