def HexLegend(hexes, name="selection", values=None,
              hx_post="/select", hx_target=None, hx_swap=None,
              direction="row", size=30, font_size=14, gap=6, item_gap=12,
              hover_fill="rgba(128,128,128,0.3)", cursor="pointer",
              **kwargs):
    """Clickable hex legend — hex swatches with external labels.
    
    Args:
        hexes: List of Hex objects (.style and .label used)
        name: Form field name (shared across group)
        values: Values to send on click (defaults to labels)
        hx_post: HTMX post URL
        hx_target: HTMX target selector
        hx_swap: HTMX swap strategy
        direction: "row" (label right of hex) or "column" (label below hex)
        size: Hex swatch diameter in pixels
        font_size: Label font size
        gap: Space between hex swatch and its label
        item_gap: Space between legend items
        hover_fill: Hover fill color on swatch
        cursor: Hover cursor
        **kwargs: Passed to wrapping Div (id, cls, style, etc.)
    
    Returns:
        FastHTML Div containing the legend
    """
    if values is None:
        values = [h.label if h.label else str(i) for i, h in enumerate(hexes)]
    
    radius = size / 2
    pad = 3
    svg_size = size + pad * 2
    
    # Touch overlay style with hover
    touch_style = StyleCSS("hex-legend-touch", fill="transparent", stroke="none", cursor=cursor)
    hover = StyleCSS("_hover", fill=hover_fill, cursor=cursor)
    touch_style.customize(hover)
    
    items = []
    for i, (hex_obj, value) in enumerate(zip(hexes, values)):
        center = MapCord(svg_size / 2, svg_size / 2)
        
        builder = SVGBuilder()
        builder.width = svg_size
        builder.height = svg_size
        builder.add_style(hex_obj.style)
        builder.add_style(touch_style)
        
        # Visual hex swatch (no text inside)
        h = Hex(radius, center, hex_obj.style)
        builder.adjust("visual", h.svg())
        
        # Touch hex with HTMX attrs
        touch = Hex(radius, center, touch_style, v=h.v)
        attrs = {"hx-post": hx_post}
        attrs["hx-vals"] = json.dumps({name: str(value)})
        if hx_target: attrs["hx-target"] = hx_target
        if hx_swap:   attrs["hx-swap"] = hx_swap
        builder.adjust("touch", touch.svg(attrs))
        
        svg_el = Div(NotStr(builder.xml()), style="flex-shrink:0; line-height:0;")
        label_text = hex_obj.label or str(value)
        label_el = Span(label_text, style=f"font-size:{font_size}px; white-space:nowrap;")
        
        # Per-item layout: row → text right, column → text below
        if direction == "row":
            item_style = f"display:flex; flex-direction:row; align-items:center; gap:{gap}px;"
        else:
            item_style = f"display:flex; flex-direction:column; align-items:center; gap:{gap}px;"
        
        items.append(Div(svg_el, label_el, style=item_style))
    
    # Outer container arranges items
    flex_dir = "row" if direction == "row" else "column"
    wrap = "flex-wrap:wrap;" if direction == "row" else ""
    container_style = f"display:flex; flex-direction:{flex_dir}; align-items:center; gap:{item_gap}px; {wrap}"
    extra_style = kwargs.pop("style", "")
    
    return Div(*items, style=f"{container_style} {extra_style}", **kwargs)


