def HexBackground(*children, levels=2, pad=5, fill="#f4edb2ff",
                  size=MapSize(300,300), shadow=True, **kwargs):
    """A hex-shaped decorative background with content overlaid.
    
    Args:
        *children: FT content to display centered over the hex
        levels: Number of concentric hex border rings
        pad: Padding between rings
        fill: Inner hex fill color
        size: MapSize(width, height) of the container
        shadow: Whether to add drop shadow
        **kwargs: HTML/HTMX attrs on the outer container Div
    """
    eles = StyleCSS.elevations()
    myStyles = []
    radius = size.width / 2
    center = MapCord(size.width / 2, size.height / 2)
    
    canvas = ""
    cur_size = MapSize(size.width, size.height)
    
    for i in range(levels):
        aStyle = eles[i]
        myStyles.append(aStyle)
        h = _stretched_hex(radius, center, aStyle, cur_size)
        canvas += h.svg() + "\n"
        cur_size = MapSize(cur_size.width - pad * 2, cur_size.height - pad * 2)
    
    inner_style = StyleCSS("hex-bg-inner", fill=fill)
    myStyles.append(inner_style)
    h = _stretched_hex(radius, center, inner_style, cur_size)
    canvas += h.svg()
    
    builder = SVGBuilder()
    builder.width = size.width
    builder.height = size.height
    for s in myStyles:
        builder.add_style(s)
    builder.updateLayers([canvas])
    
    shadow_css = "filter: drop-shadow(4px 4px 6px rgba(0,0,0,0.3));" if shadow else ""
    
    return Div(
        Div(NotStr(builder.xml()), style=f"""
            width: 100%; height: 100%; position: absolute;
            {shadow_css}
            display: flex; justify-content: center;
            transition: all 0.2s ease;
        """),
        Div(*children, style="position: relative; z-index: 1;"),
        style=f"""
            position: relative;
            width: {size.width}px; height: {size.height}px;
            display: flex; justify-content: center; align-items: center;
            transition: all 0.2s ease;
        """,
        **kwargs
    )


